//   conflict                           → ALREADY_EXISTS (duplicado) / ABORTED
//                                         (versión desactualizada, carrera)
//   rate_limited                       → RESOURCE_EXHAUSTED
//   file_too_large / unsupported_media  → INVALID_ARGUMENT / correspondiente
